"""Reproduce selected musl scanf core and byte cursor adapters."""
from pathlib import Path
import argparse,difflib,hashlib,json,shutil
parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--musl-root',required=True,type=Path);parser.add_argument('--output-dir',required=True,type=Path);args=parser.parse_args();up=args.musl_root;out=args.output_dir;out.mkdir(parents=True,exist_ok=False)
for name in ['originals','patches','reference']:(out/name).mkdir()
original=(up/'src/stdio/vfscanf.c').read_text();s=original
s=s.replace('#include "stdio_impl.h"','#include "scan_file.h"').replace('#include "shgetc.h"','#include "../strto/scan_string.h"').replace('#include "intscan.h"','#include "../strto/intscan.h"').replace('#include "floatscan.h"','#include "../strto/floatscan.h"')
s=s.replace('int vfscanf(FILE *restrict f,','int __edg_musl_vscan(struct edg_string_scan *restrict f,').replace('off_t pos = 0;','long pos = 0;')
s=s.replace('\tFLOCK(f);\n\n\tif (!f->rpos) __toread(f);\n\tif (!f->rpos) goto input_fail;\n','').replace('\tFUNLOCK(f);\n','').replace('weak_alias(vfscanf,__isoc99_vfscanf);','')
s=s.replace('case -1:','case (size_t)-1:').replace('case -2:','case (size_t)-2:')
s=s.replace('wcs = malloc(', 'wcs = (wchar_t *)malloc(').replace('wcs = dest;', 'wcs = (wchar_t *)dest;').replace('wchar_t *tmp = realloc(', 'wchar_t *tmp = (wchar_t *)realloc(').replace('s = malloc(', 's = (char *)malloc(').replace('char *tmp = realloc(', 'char *tmp = (char *)realloc(').replace('((s = dest))','((s = (char *)dest))')
s=s.replace('switch (mbrtowc(&wc, &(char){c}, 1, &st)) {','char current = (char)c;\n\t\t\t\t\tswitch (mbrtowc(&wc, &current, 1, &st)) {')
(out/'originals/vfscanf.c').write_text(original);(out/'vfscanf.c').write_text(s);(out/'patches/vfscanf.c.patch').write_text(''.join(difflib.unified_diff(original.splitlines(True),s.splitlines(True),fromfile='a/vfscanf.c',tofile='b/vfscanf.c')))
(out/'source.json').write_text(json.dumps({'version':'musl 1.2.6','releaseSha256':'d585fd3b613c66151fc3249e8ed44f77020cb5e6c1e635a616d3f9f82460512a','sources':{'vfscanf.c':{'upstream':'src/stdio/vfscanf.c','originalSha256':hashlib.sha256(original.encode()).hexdigest(),'adaptedSha256':hashlib.sha256(s.encode()).hexdigest()}},'adapters':{}},indent=2)+'\n');shutil.copyfile(up/'COPYRIGHT',out/'COPYRIGHT')

metadata=json.loads((out/"source.json").read_text())
content='#ifndef EDG_SCAN_FILE_H\n#define EDG_SCAN_FILE_H\n#include <stdio.h>\n#include <stdarg.h>\n#include "../strto/scan_string.h"\n#ifdef __cplusplus\n#define restrict __restrict\nextern "C" {\n#endif\ntypedef int (*__edg_scan_body)(void *,const char *,va_list);\nint __edg_with_file_read_lock(FILE *,__edg_scan_body,void *,const char *,va_list);\nint __edg_musl_vscan(struct edg_string_scan *,const char *,va_list);\n#ifdef __cplusplus\n}\n#endif\n#endif\n';(out/'scan_file.h').write_text(content);metadata["adapters"]['scan_file.h']=hashlib.sha256(content.encode()).hexdigest()
content='#include "scan_file.h"\nstruct edg_scan_string {const unsigned char *position;};\nstatic int string_read(void *context)\n{\n struct edg_scan_string *input=(struct edg_scan_string*)context;\n int c=*input->position;if(!c)return EOF;++input->position;return c;\n}\nstatic int file_read(void *context){return fgetc((FILE*)context);}\nstatic int file_scan_body(void *context,const char *format,va_list arguments)\n{\n struct edg_scan_input input={0,0,0,0,0,file_read,context};\n struct edg_string_scan cursor;sh_frominput(&cursor,&input);\n int result=__edg_musl_vscan(&cursor,format,arguments);\n if(input.pending)ungetc(input.last,(FILE*)context);\n return result;\n}\nint vfscanf(FILE *file,const char *format,va_list arguments)\n{return __edg_with_file_read_lock(file,file_scan_body,file,format,arguments);}\nint vsscanf(const char *text,const char *format,va_list arguments)\n{\n struct edg_scan_string text_input={(const unsigned char*)text};\n struct edg_scan_input input={0,0,0,0,0,string_read,&text_input};\n struct edg_string_scan cursor;sh_frominput(&cursor,&input);\n return __edg_musl_vscan(&cursor,format,arguments);\n}\nint vscanf(const char *format,va_list arguments){return vfscanf(stdin,format,arguments);}\nint sscanf(const char *text,const char *format,...)\n{va_list arguments;va_start(arguments,format);int result=vsscanf(text,format,arguments);va_end(arguments);return result;}\nint fscanf(FILE *file,const char *format,...)\n{va_list arguments;va_start(arguments,format);int result=vfscanf(file,format,arguments);va_end(arguments);return result;}\nint scanf(const char *format,...)\n{va_list arguments;va_start(arguments,format);int result=vfscanf(stdin,format,arguments);va_end(arguments);return result;}\n';(out/'scan_wrappers.c').write_text(content);metadata["adapters"]['scan_wrappers.c']=hashlib.sha256(content.encode()).hexdigest()
metadata['referenceOnly']={}
for name in ['shgetc.c','shgetc.h','intscan.h','floatscan.h']:
 shutil.copy2(up/'src/internal'/name,out/'reference'/name)
 metadata['referenceOnly'][name]={'upstream':'src/internal/'+name,'sha256':hashlib.sha256((out/'reference'/name).read_bytes()).hexdigest()}
(out/'source.json').write_text(json.dumps(metadata,indent=2)+'\n')
